/**
 * GitHub Node - Version 1.1
 * Discriminator: resource=workflow, operation=dispatchAndWait
 */


interface Credentials {
  githubApi: CredentialReference;
  githubOAuth2Api: CredentialReference;
  githubAppApi: CredentialReference;
}

/** Dispatch a workflow event and wait for a webhook to be called before proceeding */
export type GithubV11WorkflowDispatchAndWaitParams = {
  resource: 'workflow';
  operation: 'dispatchAndWait';
  authentication?: 'accessToken' | 'oAuth2' | 'githubAppApi' | Expression<string>;
/**
 * Repository Owner
 * @searchListMethod getUsers
 * @displayOptions.hide { operation: ["invite", "getUserIssues"] }
 * @default {"mode":"list","value":""}
 */
    owner?: { __rl: true; mode: 'list' | 'url' | 'name'; value: string; cachedResultName?: string };
/**
 * Repository Name
 * @searchListMethod getRepositories
 * @displayOptions.hide { resource: ["user", "organization"], operation: ["getRepositories"] }
 * @default {"mode":"list","value":""}
 */
    repository?: { __rl: true; mode: 'list' | 'url' | 'name'; value: string; cachedResultName?: string };
/**
 * The workflow to dispatch
 * @searchListMethod getWorkflows
 * @default {"mode":"list","value":""}
 */
    workflowId?: { __rl: true; mode: 'list' | 'filename' | 'name'; value: string; cachedResultName?: string };
/**
 * The git reference for the workflow dispatch (branch, tag, or commit SHA)
 * @searchListMethod getRefs
 * @default {"mode":"list","value":""}
 */
    ref?: { __rl: true; mode: 'list' | 'name'; value: string; cachedResultName?: string };
/**
 * JSON object with input parameters for the workflow
 * @default {}
 */
    inputs?: IDataObject | string | Expression<string>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Whether to limit how long to wait for the webhook to be called before the execution resumes
     * @default {"values":{"limitType":"afterTimeInterval","resumeAmount":45,"resumeUnit":"minutes"}}
     */
    limitWaitTime?: {
        /** Values
     */
    values?: {
      /** Sets the condition for the execution to resume. Can be a specified date or after some time.
       * @default afterTimeInterval
       */
      limitType?: 'afterTimeInterval' | 'atSpecifiedTime' | Expression<string>;
      /** The time to wait
       * @displayOptions.show { limitType: ["afterTimeInterval"] }
       * @default 1
       */
      resumeAmount?: number | Expression<number>;
      /** Unit of the interval value
       * @displayOptions.show { limitType: ["afterTimeInterval"] }
       * @default hours
       */
      resumeUnit?: 'minutes' | 'hours' | 'days' | Expression<string>;
      /** Continue execution after the specified date and time
       * @displayOptions.show { limitType: ["atSpecifiedTime"] }
       */
      maxDateAndTime?: string | Expression<string>;
    };
  };
  };
};

export type GithubV11WorkflowDispatchAndWaitOutput = {
  status?: string;
};

export type GithubV11WorkflowDispatchAndWaitNode = {
  type: 'n8n-nodes-base.github';
  version: 1.1;
  config: NodeConfig<GithubV11WorkflowDispatchAndWaitParams> & { credentials?: Credentials };
  output?: Items<GithubV11WorkflowDispatchAndWaitOutput>;
};